    moves = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    for color, delta in moves.items():
        path_cells = set()
        dr, dc = delta
        for r, c in points.get(color, []):
            rr, cc = r + dr, c + dc
